<#
  run_seeder.ps1 - non-interactive launcher for DemoIQ.ps1

  Why this exists: DemoIQ.ps1 uses Read-Host (the run-mode menu, the end-of-run RETRY
  menu), which only reads from a real console - it ignores piped stdin. That makes a
  detached/unattended launch impossible by piping. This launcher overrides Read-Host in
  the current session, then DOT-SOURCES the seeder so every Read-Host call inside it is
  answered programmatically. The seeder file itself is never modified.

  Answers provided, in the order the seeder asks:
    1. Run mode (1 or 2) <- -RunMode parameter (default 1 = Fast)
    Any further prompt (e.g. the end-of-run RETRY menu) is answered '0' = exit
    keeping whatever succeeded.

  The administrator's sign-in (scripts/admin_signin.ps1) is CONSUMED here: read from the
  encrypted session store, deleted from disk, and handed to the seeder through
  DEMOIQ_ADMIN_SESSION, which the seeder clears as soon as it reads it. Each run
  therefore needs its own sign-in, and no sign-in outlives the run on disk.

  The seeder reads its plain, owner-only config from -ConfigFile when supplied
  (forwarded to the seeder verbatim); otherwise the seeder auto-detects a *.json beside
  itself.

  Because it is fully non-interactive, it is launched DETACHED by launch_seeder.ps1
  (Start-Process on Windows; a new session via detach.js on macOS/Linux) so it
  survives the GitHub Copilot tool call.

  It only runs seeders generated by this skill's generate.js: they carry the delegated
  patch marker (scripts/platform_patch.js), which also guarantees the seeder holds no
  certificate or admin password and sends no usage telemetry.

  It writes a heartbeat marker file (<dir>\DemoIQ-Output\.run_seeder_status)
  so a monitor can tell STARTED / DONE / FAILED without attaching.

  CLEANUP RUN (-Cleanup): the same seeder prepares the tenant like a seed, deletes the
  seeded content with delegated tokens instead of seeding (scripts/cleanup_engine.ps1,
  inlined by generate.js), restores the tenant and writes DemoIQ-Output/cleanup_result.json.
  -CleanupScope LastRun|AllRuns picks the seed runs; -CleanupManifest names a
  cleanup.config (default: the administrator's OneDrive copy, else every seed run folder
  under <ws>/runs); -ArchiveLocalDeliverables zips the targeted runs' local deliverables
  into <ws>/archive first, then removes them.
#>
param(
  [Parameter(Mandatory = $true)][string]$SeederScript,
  [string]$RunMode = '1',
  [string]$ConfigFile,
  [switch]$RetryOnFail,
  [switch]$Cleanup,
  [ValidateSet('LastRun', 'AllRuns')][string]$CleanupScope = 'LastRun',
  [string]$CleanupManifest,
  [switch]$ArchiveLocalDeliverables
)

$ErrorActionPreference = 'Stop'
if ($RunMode -ne '1' -and $RunMode -ne '2') { $RunMode = '1' }

# NOTE: every launcher-local variable is prefixed __rs_ and parameters use
# uncommon names so that dot-sourcing the seeder (shared scope) cannot collide
# with the seeder's own variables.
$__rs_dir = Split-Path -Parent $SeederScript
$__rs_out = Join-Path $__rs_dir 'DemoIQ-Output'
if (-not (Test-Path $__rs_out)) { New-Item -ItemType Directory -Path $__rs_out -Force | Out-Null }
$__rs_status = Join-Path $__rs_out '.run_seeder_status'

function __rs_WriteStatus([string]$s) {
  try { Set-Content -Path $__rs_status -Value ("{0}`t{1}" -f (Get-Date -Format 's'), $s) -Encoding UTF8 } catch {}
}

# Write a STARTING sentinel IMMEDIATELY - before the sign-in check or any heavy work -
# stamped with NOW and a fresh run-id. This lets the monitor tell "a launch just began
# here" apart from a STALE prior run's status file (the bug where a days-old DONE was
# reported as the current run). If this launch never takes (e.g. the turn was interrupted
# mid-launch), the fresh STARTING timestamp still distinguishes it from an old leftover.
$__rs_runId = [guid]::NewGuid().ToString('N').Substring(0, 12)
__rs_WriteStatus ("STARTING runId=$__rs_runId")

# Only run seeders produced by this skill's generate.js: the delegated patch marker proves
# the seeder holds no certificate or admin password and carries no usage telemetry.
try {
  $__rs_head = (Get-Content -LiteralPath $SeederScript -TotalCount 3 -ErrorAction Stop) -join "`n"
} catch { $__rs_head = '' }
if ($__rs_head -notmatch 'demoiq-seed: delegated patch v2') {
  __rs_WriteStatus 'FAILED not-a-demoiq-seed-seeder (regenerate it with scripts/generate.js)'
  # Console.Error, not Write-Error: under ErrorActionPreference=Stop, Write-Error would
  # terminate before the documented exit code.
  [Console]::Error.WriteLine('This seeder was not generated by the current demoiq-seed generate.js (delegated patch v2 marker missing). Regenerate it with scripts/generate.js.')
  exit 2
}

. (Join-Path $PSScriptRoot 'session_store.ps1')
# Consume the administrator's sign-in: this run is its only user, so it leaves the disk now.
$__rs_session = Read-DemoIQSessionSecret -Name 'admin-session'
Clear-DemoIQSessionSecret -Name 'admin-session'
if ([string]::IsNullOrEmpty($__rs_session)) {
  __rs_WriteStatus 'FAILED no-admin-session (sign in with scripts/admin_signin.ps1, then launch again)'
  [Console]::Error.WriteLine('No administrator sign-in for this run (run scripts/admin_signin.ps1 first).')
  exit 2
}

# Answer queue: the run mode. Subsequent prompts (the end-of-run RETRY menu) -> '1' once
# when -RetryOnFail is set (retry failed components), otherwise '0' (exit, keep what
# succeeded). A second retry prompt always gets '0' to avoid an infinite retry loop.
# A cleanup run skips the run-mode menu, so it gets no scripted answer.
$script:__rs_answers = New-Object System.Collections.Queue
if (-not $Cleanup) { $script:__rs_answers.Enqueue($RunMode) }
$script:__rs_retryOnFail = [bool]$RetryOnFail
$script:__rs_extraCount = 0
$script:__rs_modeAsks = 0

function Read-Host {
  [CmdletBinding()]
  param([Parameter(Position = 0)]$Prompt, [switch]$AsSecureString, [switch]$MaskInput)
  $__p = [string]$Prompt
  if ($__p -match 'Enter 1 or 2') { $script:__rs_modeAsks++ }
  if ($script:__rs_modeAsks -gt 1 -and $__p -match 'Enter 1 or 2') {
    # Full mode found no earlier run (cleanup.config) and the engine asks for the mode
    # again. Unattended, continue in Fast mode: the content was authored up front.
    if ($script:__rs_modeAsks -eq 2) {
      Write-Host ' [MODE] WARN: Full mode needs an earlier run (cleanup.config) and none was found - continuing in Fast mode.' -ForegroundColor DarkYellow
    }
    $__v = '1'
  } elseif ($script:__rs_answers.Count -gt 0) {
    $__v = [string]$script:__rs_answers.Dequeue()
  } else {
    # Past the scripted answers: this is the RETRY menu (or similar).
    $script:__rs_extraCount++
    if ($script:__rs_extraCount -gt 25) {
      # A prompt that keeps rejecting the scripted answer would spin forever unattended.
      # exit (not throw: the seeder's prompt loops catch exceptions) ends the dot-sourced
      # seeder and run_seeder reports the reason.
      $env:DEMOIQ_ABORT_REASON = "stuck-at-prompt: the seeder kept asking '$($__p.Trim())' in an unattended run"
      exit 1
    }
    $__v = if ($script:__rs_retryOnFail -and $script:__rs_extraCount -eq 1) { '1' } else { '0' }
  }
  if ($AsSecureString) { return (ConvertTo-SecureString $__v -AsPlainText -Force) }
  return $__v
}

__rs_WriteStatus $(if ($Cleanup) { "STARTED cleanup scope=$CleanupScope" } else { "STARTED mode=" + $RunMode })
$__rs_seeder = $SeederScript
# Forward an explicit config path to the seeder when one was supplied. The seeder
# exposes a -ConfigFile parameter; passing it (via splat on the dot-source) sets
# the seeder's $PSBoundParameters['ConfigFile'] so it uses the path verbatim
# instead of auto-detecting a *.json beside itself. When omitted, the seeder
# falls back to its own default/auto-detect/picker logic.
$__rs_seederArgs = @{}
if (-not [string]::IsNullOrEmpty($ConfigFile)) { $__rs_seederArgs['ConfigFile'] = $ConfigFile }
# The seeder can call `exit` directly on early failures (config not found, an
# administrator sign-in it cannot use). An `exit` inside the dot-sourced seeder returns
# to this launcher with $LASTEXITCODE set; the catch below then records the reason the
# seeder declared (DEMOIQ_ABORT_REASON). The finally backstop still turns any other
# unwind (e.g. a stopped pipeline) into an explicit FAILED heartbeat instead of a
# forever-STARTED wedge that the monitor misreads as running/stalled.
$script:__rs_terminal = $false
try {
  # Tell the seeder it is running under this launcher (it then stops instead of
  # prompting where nobody can answer).
  $env:DEMOIQ_LAUNCHER = '1'
  # No usage telemetry in this adaptation; also silences any upstream DemoIQ writer.
  $env:DEMOIQ_TELEMETRY = 'off'
  # The seeder sets this right before an intentional abort (e.g. its admin-token
  # fail-fast) so the heartbeat can carry the REAL reason instead of the generic
  # early-exit guess. Clear any stale value before the run.
  $env:DEMOIQ_ABORT_REASON = $null
  # The seeder persists DemoIQ-Output\seed_result.json (per-component completion counts)
  # after its end-of-run retry menu. Clear any stale copy from a prior run of this folder
  # so the completion check below can never read an old run's result.
  try { Remove-Item -LiteralPath (Join-Path $__rs_out 'seed_result.json') -Force -ErrorAction SilentlyContinue } catch {}
  try { Remove-Item -LiteralPath (Join-Path $__rs_out 'cleanup_result.json') -Force -ErrorAction SilentlyContinue } catch {}
  # A cleanup run: the seeder deletes instead of seeding (see the help above).
  $env:DEMOIQ_RUN_KIND = if ($Cleanup) { 'cleanup' } else { 'seed' }
  if ($Cleanup) {
    $__rs_ws = Get-DemoIQWorkspace
    $env:DEMOIQ_CLEANUP_SCOPE = $CleanupScope
    $env:DEMOIQ_CLEANUP_MANIFEST = $CleanupManifest
    $env:DEMOIQ_CLEANUP_SEARCH = Join-Path $__rs_ws 'runs'
    $env:DEMOIQ_CLEANUP_WORKSPACE = $__rs_ws
    $env:DEMOIQ_CLEANUP_ARCHIVE = if ($ArchiveLocalDeliverables) { '1' } else { $null }
  }
  # Hand the administrator's sign-in to the seeder, which removes it from the environment
  # as soon as it reads it (before it starts any child process).
  $env:DEMOIQ_ADMIN_SESSION = $__rs_session
  $__rs_session = $null

  # Reset native exit state so an explicit `exit N` inside the dot-sourced seeder
  # can be distinguished from stale state left by earlier helper processes.
  $global:LASTEXITCODE = 0
  . $__rs_seeder @__rs_seederArgs   # dot-source: Read-Host override applies inside the seeder
  $__rs_seederSucceeded = $?
  $__rs_seederExitCode = $LASTEXITCODE
  if (-not $__rs_seederSucceeded -and $__rs_seederExitCode -ne 0) {
    throw "Seeder exited with code $__rs_seederExitCode"
  }
  if ($Cleanup) {
    # Honest completion for a cleanup run: cleanup_result.json counts what was not removed.
    $__rs_cu = $null
    try { $__rs_cu = Get-Content -LiteralPath (Join-Path $__rs_out 'cleanup_result.json') -Raw | ConvertFrom-Json } catch {}
    if (-not $__rs_cu) { throw 'The cleanup run ended without cleanup_result.json.' }
    if (-not $__rs_cu.ok) { throw ('cleanup-failed: ' + $__rs_cu.error) }
    __rs_WriteStatus $(if ([int]$__rs_cu.failedTotal -gt 0) { 'DONE failed=' + [int]$__rs_cu.failedTotal } else { 'DONE' })
    $script:__rs_terminal = $true
    exit 0
  }
  # Honest completion: seed_result.json carries the ledger's post-retry-menu missing
  # count. missingTotal > 0 = a PARTIAL run - the heartbeat carries the count (payload
  # style like "STARTED mode=1") and seed_done reports outcome 'fail' so a run with
  # missing content is never recorded as a clean success.
  $__rs_missing = 0
  try {
    $__rs_resultFile = Join-Path $__rs_out 'seed_result.json'
    if (Test-Path -LiteralPath $__rs_resultFile) {
      $__rs_missing = [int]((Get-Content -LiteralPath $__rs_resultFile -Raw | ConvertFrom-Json).missingTotal)
    }
  } catch { $__rs_missing = 0 }
  if ($__rs_missing -gt 0) {
    __rs_WriteStatus ("DONE missing=" + $__rs_missing)
    $script:__rs_terminal = $true
  } else {
    __rs_WriteStatus 'DONE'
    $script:__rs_terminal = $true
  }
  exit 0
}
catch {
  # The seeder declares WHY it aborts (e.g. admin-session: ...) right before its `exit` or
  # `throw`; both land here, so prefer that reason over the generic exception text.
  $__rs_reason = if (-not [string]::IsNullOrEmpty($env:DEMOIQ_ABORT_REASON)) { $env:DEMOIQ_ABORT_REASON } else { $_.Exception.Message }
  __rs_WriteStatus ('FAILED ' + ($__rs_reason -replace '\s+', ' '))
  $script:__rs_terminal = $true
  Write-Error $_ -ErrorAction Continue
  exit 1
}
finally {
  # Never leave the sign-in in the environment, even when the seeder stopped before reading it.
  $env:DEMOIQ_ADMIN_SESSION = $null
  foreach ($__rs_var in 'DEMOIQ_RUN_KIND', 'DEMOIQ_CLEANUP_SCOPE', 'DEMOIQ_CLEANUP_MANIFEST', 'DEMOIQ_CLEANUP_SEARCH', 'DEMOIQ_CLEANUP_WORKSPACE', 'DEMOIQ_CLEANUP_ARCHIVE') {
    [Environment]::SetEnvironmentVariable($__rs_var, $null)
  }
  if (-not $script:__rs_terminal) {
    if (-not [string]::IsNullOrEmpty($env:DEMOIQ_ABORT_REASON)) {
      # The seeder declared WHY it aborted (e.g. admin-session-failed) - surface that.
      __rs_WriteStatus ('FAILED ' + ($env:DEMOIQ_ABORT_REASON -replace '\s+', ' '))
    } else {
      __rs_WriteStatus 'FAILED early-exit (the seeder exited before completing - usually a config file not found or an administrator sign-in it could not use; check the newest logs\DemoIQ_*.log)'
    }
  }
}
